const STYLES = `
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&display=swap');
  body { background: ${BG}; color: ${TEXT}; font-family: 'DM Sans', 'Helvetica Neue', sans-serif; }
  input, button, select { font-family: inherit; }
  button { cursor: pointer; }
  ::-webkit-scrollbar { width: 3px; }
  ::-webkit-scrollbar-thumb { background: ${MUTED}; border-radius: 4px; }
  @keyframes fadeUp { from { opacity:0; transform:translateY(20px); } to { opacity:1; transform:none; } }
  @keyframes scanPulse { 0%,100% { opacity:1; } 50% { opacity:0.4; } }
  @keyframes scanLine { 0%,100% { top:8%; } 50% { top:88%; } }
  .f1 { animation: fadeUp .35s ease both; }
  .f2 { animation: fadeUp .35s .08s ease both; }
  .f3 { animation: fadeUp .35s .16s ease both; }
  .f4 { animation: fadeUp .35s .24s ease both; }
  .scan-line { position:absolute; left:0; right:0; height:2px; background:#1B3A6B; animation:scanLine 2s ease-in-out infinite; pointer-events:none; }
`;

function Btn({ children, onClick, variant = "gold", disabled, full, style: sx = {} }) {
  const base = {
    padding: "13px 24px", borderRadius: 10, fontWeight: 600, fontSize: 15,
    border: "none", cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.45 : 1, transition: "all .15s",
    width: full ? "100%" : undefined, ...sx,
  };
  const map = {
    gold: { background: '#1B3A6B', color: '#FFFFFF' },
    outline: { background: "transparent", color: '#1B3A6B', border: `1.5px solid #1B3A6B` },
    ghost: { background: BORD, color: TEXT },
    danger: { background: RED, color: "#fff" },
  };
  return <button style={{ ...base, ...map[variant] }} onClick={onClick} disabled={disabled}>{children}</button>;
}

function Field({ label, value, onChange, type = "text", placeholder, required }) {
  const [focus, setFocus] = useState(false);
  return (
    <div style={{ marginBottom: 14 }}>
      <label style={{ display: "block", color: MUTED, fontSize: 11, textTransform: "uppercase", letterSpacing: 1.2, marginBottom: 6 }}>
        {label}{required && <span style={{ color: G }}> *</span>}
      </label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder}
        onFocus={() => setFocus(true)} onBlur={() => setFocus(false)}
        style={{ width: "100%", padding: "12px 14px", background: CARD, border: `1px solid ${focus ? G : BORD}`, borderRadius: 8, color: TEXT, fontSize: 15, outline: "none", transition: "border-color .15s" }} />
    </div>
  );
}

function QR({ data, size = 180 }) {
  return (
    <img src={`https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(data)}&bgcolor=EDD9A8&color=090806&margin=14`}
      width={size} height={size} style={{ display: "block", borderRadius: 6 }} alt="QR Code" />
  );
}

function BackBtn({ onClick }) {
  return <button onClick={onClick} style={{ background: "none", border: "none", color: MUTED, fontSize: 14, cursor: "pointer", padding: "16px 0", display: "flex", alignItems: "center", gap: 6 }}>← Retour</button>;
}

