function SelectPlateau({ capacity, sold1, sold2, onSelect, onBack }) {
  return (
    <div style={{ padding: 24, maxWidth: 500, margin: "0 auto" }}>
      <BackBtn onClick={onBack} />
      <div className="f1" style={{ fontFamily: "'Playfair Display', serif", fontSize: 26, fontWeight: 700, marginBottom: 6 }}>Choisissez votre plateau</div>
      <div style={{ color: MUTED, fontSize: 13, marginBottom: 28 }}>4 Juillet 2026 · L'Arlequin · Marseille</div>
      {[1, 2].map(n => {
        const soldN = n === 1 ? sold1 : sold2;
        const capN = n === 1 ? capacity.p1 : capacity.p2;
        const avail = capN - soldN;
        const pct = capN > 0 ? (soldN / capN) * 100 : 0;
        const full = avail <= 0;
        const badge = full ? { bg: RED + "25", c: RED, label: "Complet" } : avail <= 15 ? { bg: WARN + "25", c: WARN, label: `${avail} places` } : { bg: GREEN + "25", c: GREEN, label: "Disponible" };
        return (
          <div key={n} className={`f${n}`}
            onClick={() => !full && onSelect(n)}
            style={{ background: CARD, border: `1.5px solid ${full ? BORD : G + "60"}`, borderRadius: 18, padding: 24, marginBottom: 16, cursor: full ? "not-allowed" : "pointer", opacity: full ? 0.6 : 1, transition: "transform .15s, box-shadow .15s" }}
            onMouseEnter={e => { if (!full) { e.currentTarget.style.transform = "translateY(-3px)"; e.currentTarget.style.boxShadow = `0 12px 40px ${G}18`; }}}
            onMouseLeave={e => { e.currentTarget.style.transform = ""; e.currentTarget.style.boxShadow = ""; }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div style={{ fontSize: 10, color: MUTED, textTransform: "uppercase", letterSpacing: 1 }}>{PL[n].label}</div>
                <div style={{ fontSize: 38, fontWeight: 700, color: G, letterSpacing: 2, lineHeight: 1 }}>{PL[n].time}</div>
                <div style={{ marginTop: 8 }}>
                  <span style={{ fontSize: 24, fontWeight: 700, color: TEXT }}>{PL[n].price} €</span>
                  <span style={{ fontSize: 13, color: MUTED }}> / personne</span>
                </div>
              </div>
              <span style={{ background: badge.bg, color: badge.c, borderRadius: 20, padding: "4px 12px", fontSize: 12, fontWeight: 600 }}>{badge.label}</span>
            </div>
            <div style={{ marginTop: 16, height: 4, background: BORD, borderRadius: 2 }}>
              <div style={{ height: "100%", width: `${Math.min(100, pct)}%`, background: pct > 85 ? RED : G, borderRadius: 2, transition: "width .5s" }} />
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 6, fontSize: 11, color: MUTED }}>
              <span>{soldN} vendues</span>
              <span>{capN} places total</span>
            </div>
          </div>
        );
      })}
    </div>
  );
}

